import { api } from './api.js';

// ---- Application state -----------------------------------------------------
const state = {
  view: 'active', // active | unread | archive
  q: '',
  includedTags: [],
  excludedTags: [],
  savedViewId: null,
  sort: 'added_desc',
  page: 1,
  pageSize: 25,
  selected: new Set(),
  selectAllMatching: false,
  hasItems: false,
  prefs: { default_sort: 'added_desc', items_per_page: 25, text_size: 'medium' },
  editing: null, // bookmark being edited
  editTags: [],
};

const $ = (sel) => document.querySelector(sel);
const el = (tag, cls, txt) => {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (txt !== undefined) e.textContent = txt;
  return e;
};

function toast(msg) {
  const t = $('#toast');
  t.textContent = msg;
  t.classList.remove('hidden');
  clearTimeout(toast._t);
  toast._t = setTimeout(() => t.classList.add('hidden'), 2600);
}

// ---- Query building --------------------------------------------------------
function currentFilterParams() {
  const p = new URLSearchParams();
  if (state.savedViewId) {
    // saved view results endpoint is used separately; for list we pass id
    p.set('saved_view_id', state.savedViewId);
  } else {
    if (state.q) p.set('q', state.q);
    state.includedTags.forEach((t) => p.append('included_tags', t));
    state.excludedTags.forEach((t) => p.append('excluded_tags', t));
    p.set('view', state.view);
  }
  return p;
}

// Selector describing the complete current view for bulk actions (FR-025/025a).
function matchingSelector() {
  if (state.savedViewId) return { matching: { saved_view_id: state.savedViewId } };
  return {
    matching: {
      q: state.q,
      included_tags: state.includedTags,
      excluded_tags: state.excludedTags,
      view: state.view,
    },
  };
}

function currentSelector() {
  if (state.selectAllMatching) return matchingSelector();
  return { ids: [...state.selected] };
}

// ---- Rendering -------------------------------------------------------------
async function load() {
  const params = currentFilterParams();
  params.set('sort', state.sort);
  params.set('page', state.page);
  params.set('page_size', state.pageSize);
  let data;
  try {
    if (state.savedViewId) {
      const p2 = new URLSearchParams();
      p2.set('sort', state.sort);
      p2.set('page', state.page);
      p2.set('page_size', state.pageSize);
      data = await api.viewResults(state.savedViewId, p2);
    } else {
      data = await api.listBookmarks(params);
    }
  } catch (err) {
    if (err.status === 400) {
      renderError(err.message);
      markReady();
      return;
    }
    throw err;
  }
  renderList(data);
  await renderSidebar();
  renderActiveFilters();
  renderBulkBar();
  markReady();
}

function renderError(msg) {
  $('#bookmark-list').innerHTML = '';
  const empty = $('#empty-state');
  empty.classList.remove('hidden');
  empty.textContent = 'Search problem: ' + msg;
  $('#pager').innerHTML = '';
}

function renderList(data) {
  const listEl = $('#bookmark-list');
  listEl.innerHTML = '';
  const empty = $('#empty-state');
  if (data.items.length === 0) {
    empty.classList.remove('hidden');
    empty.textContent = emptyMessage();
  } else {
    empty.classList.add('hidden');
  }
  for (const b of data.items) {
    listEl.appendChild(renderBookmark(b));
  }
  state.hasItems = data.items.length > 0;
  renderPager(data);
}

function emptyMessage() {
  if (state.q || state.includedTags.length || state.excludedTags.length || state.savedViewId) {
    return 'No bookmarks match your search or filters.';
  }
  if (state.view === 'unread') return 'Nothing left to read — your unread list is empty.';
  if (state.view === 'archive') return 'Your archive is empty.';
  return 'No bookmarks yet. Paste a link above to save your first one.';
}

function renderBookmark(b) {
  const li = el('li', 'bookmark');
  li.dataset.id = b.id;
  if (state.selected.has(b.id) || state.selectAllMatching) li.classList.add('selected');

  const sel = el('input', 'sel');
  sel.type = 'checkbox';
  sel.checked = state.selected.has(b.id) || state.selectAllMatching;
  sel.addEventListener('change', () => {
    state.selectAllMatching = false;
    if (sel.checked) state.selected.add(b.id);
    else state.selected.delete(b.id);
    li.classList.toggle('selected', sel.checked);
    renderBulkBar();
  });
  li.appendChild(sel);

  if (b.icon_url) {
    const icon = el('img', 'favicon');
    icon.src = b.icon_url;
    icon.alt = '';
    icon.addEventListener('error', () => icon.remove());
    li.appendChild(icon);
  } else {
    li.appendChild(el('span', 'favicon'));
  }

  const body = el('div', 'body');
  const title = el('a', 'title', b.title || b.url);
  title.href = b.url;
  title.target = '_blank';
  title.rel = 'noopener';
  body.appendChild(title);
  body.appendChild(el('div', 'url', b.url));
  if (b.description) body.appendChild(el('div', 'desc', b.description));

  const meta = el('div', 'meta');
  if (!b.is_read) meta.appendChild(el('span', 'badge unread', 'Unread'));
  if (b.is_archived) meta.appendChild(el('span', 'badge archived', 'Archived'));
  for (const t of b.tags) {
    const tag = el('span', 'tag', t);
    tag.addEventListener('click', () => filterByTag(t));
    meta.appendChild(tag);
  }
  body.appendChild(meta);
  li.appendChild(body);

  if (b.preview_image_url) {
    const img = el('img', 'preview');
    img.src = b.preview_image_url;
    img.alt = '';
    img.addEventListener('error', () => img.remove());
    li.appendChild(img);
  }

  const actions = el('div', 'actions');
  const editBtn = el('button', '', 'Edit');
  editBtn.addEventListener('click', () => openEditor(b.id));
  actions.appendChild(editBtn);

  const readBtn = el('button', '', b.is_read ? 'Mark unread' : 'Mark read');
  readBtn.addEventListener('click', async () => {
    await api.updateBookmark(b.id, { is_read: !b.is_read });
    load();
  });
  actions.appendChild(readBtn);

  const archBtn = el('button', '', b.is_archived ? 'Restore' : 'Archive');
  archBtn.addEventListener('click', async () => {
    await api.updateBookmark(b.id, { is_archived: !b.is_archived });
    toast(b.is_archived ? 'Restored' : 'Archived');
    load();
  });
  actions.appendChild(archBtn);

  li.appendChild(actions);
  return li;
}

function renderPager(data) {
  const pager = $('#pager');
  pager.innerHTML = '';
  const pages = Math.max(1, Math.ceil(data.total / data.page_size));
  if (pages <= 1) return;
  const prev = el('button', '', '‹ Prev');
  prev.disabled = data.page <= 1;
  prev.addEventListener('click', () => { state.page--; load(); });
  const next = el('button', '', 'Next ›');
  next.disabled = data.page >= pages;
  next.addEventListener('click', () => { state.page++; load(); });
  pager.appendChild(prev);
  pager.appendChild(el('span', '', `Page ${data.page} of ${pages} · ${data.total} items`));
  pager.appendChild(next);
}

async function renderSidebar() {
  // Saved views
  const views = await api.listViews();
  const vlist = $('#saved-views');
  vlist.innerHTML = '';
  for (const v of views.views) {
    const li = el('li');
    const btn = el('button', '', v.name);
    btn.addEventListener('click', () => openSavedView(v.id));
    const del = el('button', '', '✕');
    del.title = 'Delete view';
    del.addEventListener('click', async (e) => {
      e.stopPropagation();
      await api.deleteView(v.id);
      if (state.savedViewId === v.id) clearFilters();
      renderSidebar();
    });
    li.appendChild(btn);
    li.appendChild(del);
    vlist.appendChild(li);
  }
  const saveBtn = el('button', 'link-btn', '+ Save current search');
  saveBtn.addEventListener('click', saveCurrentView);
  vlist.appendChild(saveBtn);

  // Tags
  const tags = await api.listTags();
  const cloud = $('#tag-cloud');
  cloud.innerHTML = '';
  for (const t of tags.tags) {
    const li = el('li');
    const span = el('span', 'tag', `${t.name} (${t.count})`);
    span.addEventListener('click', () => filterByTag(t.name));
    li.appendChild(span);
    cloud.appendChild(li);
  }
}

function renderActiveFilters() {
  const box = $('#active-filters');
  box.innerHTML = '';
  const add = (label, onRemove) => {
    const chip = el('span', 'chip');
    chip.appendChild(el('span', '', label));
    const x = el('button', '', '✕');
    x.addEventListener('click', onRemove);
    chip.appendChild(x);
    box.appendChild(chip);
  };
  if (state.savedViewId) {
    add('Saved view', () => clearFilters());
    return;
  }
  state.includedTags.forEach((t) =>
    add('#' + t, () => { state.includedTags = state.includedTags.filter((x) => x !== t); state.page = 1; load(); })
  );
  state.excludedTags.forEach((t) =>
    add('-#' + t, () => { state.excludedTags = state.excludedTags.filter((x) => x !== t); state.page = 1; load(); })
  );
}

function renderBulkBar() {
  const bar = $('#bulk-bar');
  // The bar (and its "select all matching" control) is available whenever there
  // are items to act on, or an active selection exists.
  const show = state.hasItems || state.selectAllMatching || state.selected.size > 0;
  bar.classList.toggle('hidden', !show);
  $('#select-all-matching').checked = state.selectAllMatching;
  $('#bulk-count').textContent = state.selectAllMatching
    ? 'All matching selected'
    : `${state.selected.size} selected`;
}

// ---- Filters / navigation --------------------------------------------------
function filterByTag(tag) {
  state.savedViewId = null;
  if (!state.includedTags.includes(tag)) state.includedTags.push(tag);
  state.page = 1;
  clearSelection();
  load();
}

function clearFilters() {
  state.q = '';
  state.includedTags = [];
  state.excludedTags = [];
  state.savedViewId = null;
  state.page = 1;
  $('#search-box').value = '';
  clearSelection();
  load();
}

function openSavedView(id) {
  state.savedViewId = id;
  state.q = '';
  state.includedTags = [];
  state.excludedTags = [];
  state.page = 1;
  $('#search-box').value = '';
  clearSelection();
  load();
}

async function saveCurrentView() {
  const name = prompt('Name this view:');
  if (!name) return;
  await api.createView({
    name,
    query: state.q,
    included_tags: state.includedTags,
    excluded_tags: state.excludedTags,
  });
  toast('View saved');
  renderSidebar();
}

function clearSelection() {
  state.selected.clear();
  state.selectAllMatching = false;
  renderBulkBar();
}

// ---- Bulk actions ----------------------------------------------------------
async function runBulk(action) {
  const selector = currentSelector();
  if (action.delete) {
    const { affected } = await api.bulkCount(selector);
    if (!confirm(`Delete ${affected} bookmark(s)? This cannot be undone.`)) return;
    action.confirm = true;
  }
  const { affected } = await api.bulk(selector, action);
  toast(`Updated ${affected} bookmark(s)`);
  clearSelection();
  load();
}

// ---- Editor ----------------------------------------------------------------
async function openEditor(id) {
  const { bookmark } = await api.getBookmark(id);
  state.editing = bookmark;
  state.editTags = [...bookmark.tags];
  $('#editor-banner').classList.add('hidden');
  $('#edit-url').value = bookmark.url;
  $('#edit-title').value = bookmark.title;
  $('#edit-description').value = bookmark.description;
  $('#edit-note').innerHTML = bookmark.note_html || '';
  $('#edit-tags').value = '';
  renderEditTagChips();
  renderPreservedList(bookmark);
  $('#preserve-status').textContent = '';
  $('#editor-modal').classList.remove('hidden');
}

function renderEditTagChips() {
  const box = $('#edit-tag-chips');
  box.innerHTML = '';
  state.editTags.forEach((t) => {
    const chip = el('span', 'chip');
    chip.appendChild(el('span', '', t));
    const x = el('button', '', '✕');
    x.addEventListener('click', () => {
      state.editTags = state.editTags.filter((y) => y !== t);
      renderEditTagChips();
    });
    chip.appendChild(x);
    box.appendChild(chip);
  });
}

function renderPreservedList(bookmark) {
  const box = $('#preserved-list');
  box.innerHTML = '';
  for (const p of bookmark.preserved || []) {
    const link = el('a', '', `Preserved (${p.kind}) — ${new Date(p.captured_at).toLocaleString()}`);
    link.href = `/api/bookmarks/${bookmark.id}/preserved/${p.id}`;
    link.target = '_blank';
    box.appendChild(link);
  }
}

async function saveEditor() {
  const id = state.editing.id;
  const patch = {
    url: $('#edit-url').value.trim(),
    title: $('#edit-title').value,
    description: $('#edit-description').value,
    note_html: $('#edit-note').innerHTML,
    tags: state.editTags,
  };
  try {
    await api.updateBookmark(id, patch);
    $('#editor-modal').classList.add('hidden');
    toast('Saved');
    load();
  } catch (err) {
    if (err.status === 409) {
      const banner = $('#editor-banner');
      banner.classList.remove('hidden');
      banner.textContent = 'Another bookmark already uses this address.';
    } else if (err.status === 400) {
      const banner = $('#editor-banner');
      banner.classList.remove('hidden');
      banner.textContent = err.message;
    } else {
      throw err;
    }
  }
}

// ---- Tag input with suggestions -------------------------------------------
function setupTagInput() {
  const input = $('#edit-tags');
  const sugg = $('#tag-suggestions');
  let active = -1;
  let items = [];

  const hide = () => { sugg.classList.add('hidden'); active = -1; };
  const commit = (val) => {
    const t = (val || input.value).trim();
    if (t && !state.editTags.some((x) => x.toLowerCase() === t.toLowerCase())) {
      state.editTags.push(t);
      renderEditTagChips();
    }
    input.value = '';
    hide();
  };

  input.addEventListener('input', async () => {
    const q = input.value.trim();
    if (!q) return hide();
    const { tags } = await api.suggestTags(q);
    items = tags.filter((t) => !state.editTags.includes(t));
    sugg.innerHTML = '';
    items.forEach((t, i) => {
      const li = el('li', '', t);
      li.addEventListener('mousedown', (e) => { e.preventDefault(); commit(t); });
      sugg.appendChild(li);
    });
    sugg.classList.toggle('hidden', items.length === 0);
  });

  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') { e.preventDefault(); if (active >= 0 && items[active]) commit(items[active]); else commit(); }
    else if (e.key === 'ArrowDown') { e.preventDefault(); active = Math.min(active + 1, items.length - 1); highlight(); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); active = Math.max(active - 1, 0); highlight(); }
    else if (e.key === 'Escape') hide();
  });
  function highlight() {
    [...sugg.children].forEach((li, i) => li.classList.toggle('active', i === active));
  }
  input.addEventListener('blur', () => setTimeout(hide, 150));
}

// ---- Note editor toolbar ---------------------------------------------------
function setupNoteEditor() {
  document.querySelectorAll('.note-toolbar button').forEach((btn) => {
    btn.addEventListener('click', () => {
      const cmd = btn.dataset.cmd;
      const arg = btn.dataset.arg;
      if (cmd === 'createLink') {
        const url = prompt('Link URL:');
        if (url) document.execCommand('createLink', false, url);
      } else {
        document.execCommand(cmd, false, arg || null);
      }
      $('#edit-note').focus();
    });
  });
}
:root {
  --bg: #f5f6f8;
  --panel: #ffffff;
  --border: #e2e5ea;
  --text: #1c2230;
  --muted: #6b7280;
  --accent: #2563eb;
  --danger: #dc2626;
  --radius: 10px;
  --fs: 15px;
}
html[data-text-size='small'] { --fs: 13px; }
html[data-text-size='medium'] { --fs: 15px; }
html[data-text-size='large'] { --fs: 17px; }

* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  font-size: var(--fs);
  color: var(--text);
  background: var(--bg);
}
.hidden { display: none !important; }

.topbar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 12px 20px;
  background: var(--panel);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 10;
}
.brand { font-size: 1.1rem; margin: 0; white-space: nowrap; }
.add-form { flex: 1; display: flex; gap: 8px; max-width: 640px; }
.add-form input { flex: 1; }
input, textarea, select, button {
  font: inherit;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
  color: var(--text);
}
button { cursor: pointer; background: #f3f4f6; }
button:hover { background: #e9ebef; }
button.primary, .add-form button { background: var(--accent); color: #fff; border-color: var(--accent); }
button.primary:hover, .add-form button:hover { filter: brightness(1.05); }
button.danger { color: var(--danger); border-color: #f3c9c9; background: #fff5f5; }
.icon-btn { font-size: 1.1rem; }

.layout { display: flex; align-items: flex-start; }
.sidebar {
  width: 230px;
  padding: 16px;
  border-right: 1px solid var(--border);
  height: calc(100vh - 57px);
  overflow-y: auto;
  position: sticky;
  top: 57px;
}
.views-nav { display: flex; flex-direction: column; gap: 4px; }
.view-link, .link-btn { text-align: left; background: none; border: none; padding: 8px 10px; border-radius: 8px; width: 100%; }
.view-link:hover, .link-btn:hover { background: #eceef2; }
.view-link.active { background: #e0e7ff; color: var(--accent); font-weight: 600; }
.sidebar-section { margin-top: 20px; }
.sidebar-head { font-size: 0.8rem; text-transform: uppercase; letter-spacing: .04em; color: var(--muted); margin-bottom: 6px; }
.saved-views, .tag-cloud { list-style: none; padding: 0; margin: 0; }
.saved-views li, .tag-cloud li { padding: 4px 0; }
.saved-views button { background: none; border: none; padding: 4px 6px; }
.tag-cloud .tag { display: inline-block; background: #eef2ff; color: var(--accent); border-radius: 20px; padding: 2px 10px; font-size: .85rem; cursor: pointer; }
.io { display: flex; flex-direction: column; gap: 4px; }

.content { flex: 1; padding: 20px; max-width: 900px; }
.toolbar { display: flex; gap: 10px; margin-bottom: 12px; }
#search-box { flex: 1; }
.active-filters { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 10px; }
.active-filters .chip { background: #e0e7ff; color: var(--accent); }

.chip {
  display: inline-flex; align-items: center; gap: 6px;
  background: #eef2ff; color: var(--accent);
  border-radius: 20px; padding: 3px 10px; font-size: .85rem;
}
.chip button { background: none; border: none; padding: 0; color: inherit; }
.chips { display: flex; flex-wrap: wrap; gap: 6px; margin: 6px 0; }

.bulk-bar {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  background: #fffbe9; border: 1px solid #f2e6b8; padding: 8px 12px;
  border-radius: var(--radius); margin-bottom: 12px;
}
.bulk-count { color: var(--muted); }
.bulk-tag { width: 120px; }

.bookmark-list { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 10px; }
.bookmark {
  display: flex; gap: 12px; align-items: flex-start;
  background: var(--panel); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 12px 14px;
}
.bookmark.selected { border-color: var(--accent); box-shadow: 0 0 0 2px #dbe4ff; }
.bookmark .sel { margin-top: 3px; }
.bookmark .favicon { width: 20px; height: 20px; border-radius: 4px; margin-top: 2px; background: #eee; object-fit: cover; flex: 0 0 auto; }
.bookmark .body { flex: 1; min-width: 0; }
.bookmark .title { font-weight: 600; font-size: 1rem; text-decoration: none; color: var(--text); }
.bookmark .title:hover { color: var(--accent); }
.bookmark .url { color: var(--muted); font-size: .8rem; word-break: break-all; }
.bookmark .desc { margin: 4px 0; color: #374151; }
.bookmark .meta { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; margin-top: 6px; }
.bookmark .meta .tag { cursor: pointer; }
.bookmark .badge { font-size: .72rem; padding: 1px 7px; border-radius: 20px; }
.badge.unread { background: #fde68a; color: #92400e; }
.badge.archived { background: #e5e7eb; color: #374151; }
.bookmark .actions { display: flex; gap: 4px; flex-wrap: wrap; }
.bookmark .actions button { padding: 4px 8px; font-size: .8rem; }
.preview { width: 90px; height: 60px; object-fit: cover; border-radius: 8px; flex: 0 0 auto; }

.empty-state { text-align: center; color: var(--muted); padding: 60px 20px; }
.pager { display: flex; gap: 8px; justify-content: center; margin-top: 16px; align-items: center; }

.modal { position: fixed; inset: 0; background: rgba(15,23,42,.45); display: flex; align-items: flex-start; justify-content: center; padding: 40px 16px; overflow-y: auto; z-index: 50; }
.modal-card { background: #fff; border-radius: 14px; padding: 22px; width: 100%; max-width: 620px; display: flex; flex-direction: column; gap: 10px; }
.modal-card h2 { margin: 0 0 6px; }
.modal-card label { display: flex; flex-direction: column; gap: 4px; font-size: .85rem; color: var(--muted); }
.modal-card label input, .modal-card label textarea, .modal-card label select { color: var(--text); font-size: var(--fs); }
.modal-actions { display: flex; gap: 8px; align-items: center; margin-top: 8px; }
.spacer { flex: 1; }
.note-toolbar { display: flex; gap: 4px; }
.note-toolbar button { padding: 4px 8px; }
.note-editor { min-height: 90px; border: 1px solid var(--border); border-radius: 8px; padding: 8px 10px; background: #fff; }
.note-editor:focus { outline: 2px solid #dbe4ff; }
.tag-input-wrap { position: relative; }
.suggestions { position: absolute; top: 100%; left: 0; right: 0; background: #fff; border: 1px solid var(--border); border-radius: 8px; list-style: none; margin: 2px 0 0; padding: 4px; z-index: 5; max-height: 180px; overflow-y: auto; }
.suggestions li { padding: 6px 8px; border-radius: 6px; cursor: pointer; }
.suggestions li:hover, .suggestions li.active { background: #eef2ff; }
.banner { background: #fff7ed; border: 1px solid #fed7aa; color: #9a3412; padding: 8px 10px; border-radius: 8px; }
.preserve-row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-top: 6px; }
.preserve-status { color: var(--muted); font-size: .85rem; }
.preserved-list { display: flex; flex-direction: column; gap: 4px; font-size: .85rem; }

.toast { position: fixed; bottom: 20px; left: 50%; transform: translateX(-50%); background: #111827; color: #fff; padding: 10px 16px; border-radius: 8px; z-index: 100; }
import { test, expect } from '@playwright/test';

// End-to-end flows over the real app (FR core loop). The webServer is started by
// playwright.config.js. Each test seeds via the API for determinism.

async function reset(request) {
  // Delete everything so tests are independent.
  const res = await request.get('/api/bookmarks?page_size=1000&view=active');
  const active = (await res.json()).items;
  const arch = (await (await request.get('/api/bookmarks?page_size=1000&view=archive')).json()).items;
  for (const b of [...active, ...arch]) {
    await request.delete(`/api/bookmarks/${b.id}`);
  }
}

test('app loads and marks harness ready', async ({ page }) => {
  await page.goto('/');
  await expect(page.locator('[data-harness-ready="true"]')).toBeVisible();
});

test('save, search, and open a bookmark', async ({ page, request }) => {
  await reset(request);
  await request.post('/api/bookmarks', {
    data: { url: 'https://example.com/', title: 'Example Site', tags: ['demo'] },
  });
  await page.goto('/');
  await expect(page.locator('.bookmark .title', { hasText: 'Example Site' })).toBeVisible();

  // Search narrows the list.
  await page.fill('#search-box', 'nonexistent-term-xyz');
  await expect(page.locator('#empty-state')).toBeVisible();
  await page.fill('#search-box', 'Example');
  await expect(page.locator('.bookmark .title', { hasText: 'Example Site' })).toBeVisible();

  // Opening the title targets a new tab.
  const link = page.locator('.bookmark .title');
  await expect(link).toHaveAttribute('target', '_blank');
  await expect(link).toHaveAttribute('href', 'https://example.com/');
});

test('archive removes from active and shows in archive view', async ({ page, request }) => {
  await reset(request);
  const created = await (
    await request.post('/api/bookmarks', { data: { url: 'https://arch.test/1', title: 'Archive Me' } })
  ).json();
  await page.goto('/');
  await page.locator('.bookmark', { hasText: 'Archive Me' }).getByRole('button', { name: 'Archive' }).click();
  await expect(page.locator('.bookmark', { hasText: 'Archive Me' })).toHaveCount(0);
  await page.locator('.view-link[data-view="archive"]').click();
  await expect(page.locator('.bookmark', { hasText: 'Archive Me' })).toBeVisible();
});

test('bulk select-all-matching archives the whole current view', async ({ page, request }) => {
  await reset(request);
  for (let i = 0; i < 5; i++) {
    await request.post('/api/bookmarks', { data: { url: `https://bulk.test/${i}`, title: `B${i}`, tags: ['bulk'] } });
  }
  await page.goto('/');
  await expect(page.locator('.bookmark')).toHaveCount(5);
  await page.check('#select-all-matching');
  await page.locator('#bulk-bar button[data-bulk="archive"]').click();
  await expect(page.locator('.bookmark')).toHaveCount(0);
  await page.locator('.view-link[data-view="archive"]').click();
  await expect(page.locator('.bookmark')).toHaveCount(5);
});
